import unicodedata
import hashlib
import hmac
import os
import re
import html
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import parse_qs, unquote
import json
import secrets
import time

SECRET_KEY = os.environ.get('APP_SECRET_KEY', secrets.token_hex(32))
SESSION_STORE = {}

def constant_time_compare(a: bytes, b: bytes) -> bool:
    return hmac.compare_digest(a, b)

def generate_csrf_token(session_id: str) -> str:
    return hmac.new(SECRET_KEY.encode(), session_id.encode(), hashlib.sha256).hexdigest()

def validate_header_value(value: str) -> bool:
    """Validate that a header value doesn't contain injection characters.
    Checks for CR, LF, and null bytes that could enable response splitting."""
    forbidden = ['\r', '\n', '\x00']
    for char in forbidden:
        if char in value:
            return False
    if len(value) > 4096:
        return False
    return True

def normalize_display_name(name: str) -> str:
    """Normalize unicode display names to canonical form for consistent storage.
    Uses NFKC normalization for compatibility decomposition followed by canonical composition."""
    normalized = unicodedata.normalize('NFKC', name)
    return normalized

def sanitize_redirect_url(url: str) -> str:
    """Sanitize redirect URL to prevent open redirect."""
    if not url.startswith('/'):
        return '/'
    if '//' in url or '\\' in url:
        return '/'
    return url

def build_response_headers(display_name: str, redirect_path: str, session_id: str) -> dict:
    """Build response headers for the login success response.
    Sets a welcome header with the user's display name and redirect location."""
    # Normalize FIRST for consistent representation
    safe_name = normalize_display_name(display_name)

    # Validate the normalized name for header safety AFTER normalization
    if not validate_header_value(safe_name):
        safe_name = 'User'

    # Sanitize redirect
    safe_redirect = sanitize_redirect_url(redirect_path)

    headers = {
        'Content-Type': 'text/html; charset=utf-8',
        'X-Welcome-User': safe_name,
        'Location': safe_redirect,
        'X-Session-ID': session_id,
        'X-Content-Type-Options': 'nosniff',
        'Cache-Control': 'no-store, no-cache, must-revalidate',
    }
    return headers

def authenticate_user(username: str, password: str) -> dict:
    """Authenticate user against stored credentials.
    Returns user info dict or None."""
    # Simulated user database lookup
    stored_users = {
        'admin': {
            'password_hash': hashlib.pbkdf2_hmac('sha256', b'admin_pass', b'salt_admin_2024', 100000).hex(),
            'display_name': 'Administrator',
            'role': 'admin'
        },
        'user1': {
            'password_hash': hashlib.pbkdf2_hmac('sha256', b'user1_pass', b'salt_user1_2024', 100000).hex(),
            'display_name': 'Regular User',
            'role': 'user'
        }
    }

    if username not in stored_users:
        # Constant-time comparison to prevent timing attacks
        hashlib.pbkdf2_hmac('sha256', password.encode(), b'dummy_salt', 100000)
        return None

    user = stored_users[username]
    computed_hash = hashlib.pbkdf2_hmac('sha256', password.encode(), f'salt_{username}_2024'.encode(), 100000).hex()

    if not constant_time_compare(computed_hash.encode(), user['password_hash'].encode()):
        return None

    return user

def create_session(username: str, user_info: dict) -> str:
    """Create a new session for authenticated user."""
    session_id = secrets.token_urlsafe(32)
    SESSION_STORE[session_id] = {
        'username': username,
        'display_name': user_info['display_name'],
        'role': user_info['role'],
        'created_at': time.time(),
        'expires_at': time.time() + 3600
    }
    return session_id

def handle_login(request_body: str, custom_display_name: str = None, redirect_url: str = '/dashboard') -> tuple:
    """Handle login request. Returns (status_code, headers, body)."""
    try:
        params = parse_qs(request_body)
        username = params.get('username', [''])[0]
        password = params.get('password', [''])[0]

        if not username or not password:
            return (400, {'Content-Type': 'text/html'}, '<h1>Missing credentials</h1>')

        # Rate limiting check (simplified)
        if len(username) > 64 or len(password) > 128:
            return (400, {'Content-Type': 'text/html'}, '<h1>Invalid input</h1>')

        user_info = authenticate_user(username, password)
        if user_info is None:
            return (401, {'Content-Type': 'text/html'}, '<h1>Authentication failed</h1>')

        session_id = create_session(username, user_info)

        # Use custom display name if provided (e.g., from profile settings)
        # Otherwise use the stored display name
        display_name = custom_display_name if custom_display_name else user_info['display_name']

        headers = build_response_headers(display_name, redirect_url, session_id)

        # HTML-escape the display name before inserting into the HTML body to prevent XSS
        body = f'<html><body><h1>Welcome, {html.escape(display_name)}</h1><p>Redirecting...</p></body></html>'

        return (302, headers, body)

    except Exception as e:
        return (500, {'Content-Type': 'text/html'}, '<h1>Internal Server Error</h1>')

def handle_profile_update(session_id: str, new_display_name: str) -> tuple:
    """Handle profile display name update."""
    if session_id not in SESSION_STORE:
        return (401, {'Content-Type': 'text/html'}, '<h1>Unauthorized</h1>')

    session = SESSION_STORE[session_id]
    if time.time() > session['expires_at']:
        del SESSION_STORE[session_id]
        return (401, {'Content-Type': 'text/html'}, '<h1>Session expired</h1>')

    # Validate and normalize the new display name
    if len(new_display_name) > 128:
        return (400, {'Content-Type': 'text/html'}, '<h1>Name too long</h1>')

    # Store the display name (will be validated when used in headers)
    session['display_name'] = new_display_name

    return (200, {'Content-Type': 'text/html'}, '<h1>Profile updated</h1>')
